import csv
import io
import re
from collections import Counter
from typing import List, Dict, Any

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def split_physical_rows(all_lines: List[str]) -> List[str]:
        rows = []
        buf = []
        in_quotes = False
        for line in all_lines:
            if not buf and not line.strip():
                continue
            buf.append(line)
            i = 0
            while i < len(line):
                if line[i] == '"':
                    if in_quotes and i + 1 < len(line) and line[i + 1] == '"':
                        i += 1
                    else:
                        in_quotes = not in_quotes
                i += 1
            if not in_quotes:
                rows.append("\n".join(buf))
                buf = []
        if buf:
            rows.append("\n".join(buf))
        return rows

    def parse_rows(candidate_text: str) -> List[List[str]]:
        try:
            return list(csv.reader(io.StringIO(candidate_text), delimiter=',', quotechar='"', doublequote=True, skipinitialspace=False))
        except Exception:
            return []

    physical_rows = split_physical_rows(lines)
    nonempty = [r for r in physical_rows if r.strip()]
    if not nonempty:
        return {"columns": [], "rows": []}

    header_idx = 0
    header = None
    data_start = 0
    for i, row in enumerate(nonempty[:10]):
        parsed = parse_rows(row)
        if parsed and len(parsed[0]) >= 2:
            vals = parsed[0]
            if all(re.fullmatch(r"[A-Za-z0-9 _\-/'\"().]+", v or "") for v in vals[:min(5, len(vals))]):
                header = vals
                header_idx = i
                data_start = i + 1
                break
    if header is None:
        parsed0 = parse_rows(nonempty[0])
        header = parsed0[0] if parsed0 else []
        data_start = 1

    rows = []
    for row in nonempty[data_start:]:
        parsed = parse_rows(row)
        if not parsed:
            continue
        for rec in parsed:
            if len(rec) == 0:
                continue
            if len(rec) < len(header):
                rec = rec + [""] * (len(header) - len(rec))
            elif len(rec) > len(header):
                rec = rec[:len(header)-1] + [",".join(rec[len(header)-1:])]
            rows.append([str(x) for x in rec])

    return {"columns": [str(x) for x in header], "rows": rows}
